const plural=(n,one,few,many)=>{const x=n%100;return x>=11&&x<=19?many:n%10===1?one:n%10>=2&&n%10<=4?few:many;};
let storageFailed=false, recoveryText=null;
function loadData(){try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){try{return validateData(JSON.parse(raw));}catch{recoveryText=raw;storageFailed=true;return createInitialData(false);}}}catch{storageFailed=true;}return createInitialData(true);}
let data=loadData();
