let timer={mode:'rest',running:false,deadline:0,duration:data.settings.rest,remaining:data.settings.rest,elapsed:0,startedAt:0,rounds:8,work:30,recovery:15};
try{const stored=JSON.parse(localStorage.getItem('forma.timer.v1')||'null');if(stored&&['rest','stopwatch','interval'].includes(stored.mode)&&Number.isFinite(stored.deadline)&&Number.isFinite(stored.duration)&&Number.isFinite(stored.remaining))timer={...timer,...stored};}catch{}
let audioContext=null;
function unlockAudio(){try{if(!audioContext)audioContext=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();}catch{}}
function beep(){if(!data.settings.sound)return;try{unlockAudio();for(let i=0;i<3;i++){const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.frequency.value=740+i*120;gain.gain.setValueAtTime(.065,audioContext.currentTime+i*.22);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+i*.22+.16);oscillator.start(audioContext.currentTime+i*.22);oscillator.stop(audioContext.currentTime+i*.22+.18);}}catch{}if(navigator.vibrate)navigator.vibrate([180,100,180]);}
function persist(){if(recoveryText){toast('Сначала скачайте повреждённую копию в настройках и восстановите данные.');return false;}try{if(!cloud?.saveLocal(data))localStorage.setItem(STORAGE_KEY,JSON.stringify(data));storageFailed=false;return true;}catch{storageFailed=true;toast('Не удалось сохранить данные. Скачайте резервную копию в настройках.');return false;}}
function persistTimer(){try{localStorage.setItem('forma.timer.v1',JSON.stringify(timer));}catch{}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('visible'),4200);}
const unit=()=>data.settings.unit==='lb'?'lb':'кг';
const displayWeight=kg=>Math.round(kg*(data.settings.unit==='lb'?2.2046226218:1)*100)/100;
const fromWeight=value=>Math.round(num(value)/(data.settings.unit==='lb'?2.2046226218:1)*10000)/10000;
const weightLabel=kg=>`${fmt(displayWeight(kg),1)} ${unit()}`;
const btn=(action,text,ico,style='outline',attrs='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${attrs}>${ico?icon(ico,16):''}${text}</button>`;
const ibtn=(action,ico,label,attrs='')=>`<button type="button" class="icon-btn" data-action="${action}" title="${esc(label)}" aria-label="${esc(label)}" ${attrs}>${icon(ico)}</button>`;
const empty=(title,description,action='',label='',ico='dumbbell')=>`<div class="empty">${icon(ico)}<h3>${title}</h3><p>${description}</p>${action?btn(action,label,'plus','primary'):''}</div>`;
