function navItem([id,ico,label]){return `<a href="#${id}" class="nav-item ${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ico)}${label}</a>`;}
function heading(title,description,action='start',label='Начать тренировку',ico='plus'){return `<div class="heading"><div><h1>${title}</h1><p>${description}</p></div>${action?btn(action,label,ico,'primary','aria-label="'+label+'"'):''}</div>`;}
function activeBanner(){return data.active?`<div class="active-banner between"><div class="flex">${icon('timer',18)}<span>Тренировка ${data.active.pausedAt?'на паузе':'идёт'} · <b data-workout-clock>${formatTime(totalSeconds(data.active))}</b></span></div>${btn('resume','Продолжить','arrow','sm')}</div>`:'';}
function sessionRows(sessions){return sessions.map(s=>`<button type="button" class="session-row" style="width:100%;background:none;text-align:left" data-action="session-detail" data-id="${esc(s.id)}"><span class="session-marker">${icon('dumbbell')}</span><span class="grow"><span class="session-name">${esc(s.name)}</span><span class="session-meta" style="display:block">${dateLabel(s.date)} · ${Math.round(s.duration/60)} мин · ${s.exercises.length} ${plural(s.exercises.length,'упражнение','упражнения','упражнений')}</span></span><span class="session-vol">${weightLabel(volume(s))}<small>объём</small></span>${icon('chevron',13)}</button>`).join('');}
function weekStrip(){const start=weekStart();return `<div class="week-strip">${Array.from({length:7},(_,i)=>{const d=dateKey(addDays(start,i)),done=data.sessions.some(s=>s.date===d),planned=data.schedule[d];return `<button type="button" class="day ${d===dateKey()?'today':''} ${done?'done':planned?'planned':''}" data-action="day" data-date="${d}" aria-label="${dateLabel(d,{day:'numeric',month:'long'})}${done?', есть тренировка':planned?', запланирована тренировка':''}"><span class="weekday">${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'][i]}</span><span class="day-no">${new Date(d+'T12:00:00').getDate()}</span><span class="day-dot"></span></button>`;}).join('')}</div>`;}
function goalCards(){const recs=records(data),month=dateKey().slice(0,7);return data.goals.map(g=>{const value=g.type==='sessions'?data.sessions.filter(s=>s.date.startsWith(month)).length:recs.find(r=>r.exerciseId===g.exerciseId)?.weight||0;return `<div class="goal"><div class="between"><span class="goal-name">${esc(g.name)}</span>${ibtn('delete-goal','close','Удалить цель',`data-id="${esc(g.id)}"`)}</div><div class="progress-track"><span style="width:${Math.min(100,value/g.target*100)}%"></span></div><div class="between goal-value"><span>${g.type==='weight'?weightLabel(value)+' / '+weightLabel(g.target):`${value} из ${g.target} тренировок`}</span><span>${Math.min(100,Math.round(value/g.target*100))}%</span></div></div>`;}).join('')||'<p class="muted small">Поставь первую цель и следи за результатом.</p>';}
function volumeChart(){const axisUnit=data.settings.unit==='kg'?'т':' тыс.';const count=range===7?7:range===28?4:12,step=range===7?1:7;const points=Array.from({length:count},(_,i)=>{const end=dateKey(addDays(new Date(),-(count-1-i)*step)),start=dateKey(addDays(end,-step+1));return {label:step===1?dateLabel(end,{weekday:'short'}):dateLabel(end),value:data.sessions.filter(s=>s.date>=start&&s.date<=end).reduce((v,s)=>v+volume(s),0)};});const max=Math.max(...points.map(p=>p.value),1);return `<div class="chart-wrap"><span class="chart-y top">${fmt(displayWeight(max)/1000,1)}${axisUnit}</span><span class="chart-y mid">${fmt(displayWeight(max/2)/1000,1)}${axisUnit}</span><span class="chart-y bottom">0</span><div class="bar-chart" data-columns="${count}" role="img" aria-label="Объём тренировок по периодам: ${points.map(p=>p.label+' '+weightLabel(p.value)).join(', ')}">${points.map(p=>`<div class="chart-col"><div class="bar" style="height:${p.value/max*100}%" title="${p.label}: ${weightLabel(p.value)}"></div><span class="bar-label">${p.label}</span></div>`).join('')}</div>${data.sessions.length?'':'<div class="chart-empty">График появится после первой тренировки</div>'}</div>`;}
